using System;using System.Text;using System.Text.Json;using System.Runtime.InteropServices;class KnownFolderReadOnly {static void Main(){using var m=new System.IO.MemoryStream();using(var w=new Utf8JsonWriter(m)){w.WriteStartObject();w.WriteString("schema","r80-native-knownfolder-observation-v1");w.WriteString("runtime",RuntimeInformation.FrameworkDescription);w.WriteString("programFiles",Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles));w.WriteString("commonApplicationData",Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData));w.WriteString("system",Environment.SystemDirectory);w.WriteBoolean("protectedFilesOpened",false);w.WriteBoolean("tasksOpened",false);w.WriteEndObject();}Console.WriteLine(Encoding.UTF8.GetString(m.ToArray()));}}